  navToggle.setAttribute("aria-expanded", String(isOpen));
  primaryNav.classList.toggle("is-open", isOpen);
  document.body.classList.toggle("nav-open", isOpen);
}

navToggle.addEventListener("click", () => {
  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
  setNavOpen(!isOpen);
});

primaryNav.addEventListener("click", (event) => {
  if (event.target.closest("a")) {
    setNavOpen(false);
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && navToggle.getAttribute("aria-expanded") === "true") {
    setNavOpen(false);
    navToggle.focus();
  }
});

addToCartButtons.forEach((button) => {
  const productName = button.dataset.product;
  button.setAttribute("aria-label", `${button.textContent.trim()}: ${productName}`);

  button.addEventListener("click", () => {
    bagCount += 1;
    cartCount.textContent = String(bagCount);
    cartCountText.textContent = `${bagCount} ${bagCount === 1 ? "item" : "items"}`;
    cartLink.setAttribute(
      "aria-label",
      `Shopping bag with ${bagCount} ${bagCount === 1 ? "item" : "items"}`
    );
    announce(`${productName} added to bag. Bag now has ${bagCount} ${bagCount === 1 ? "item" : "items"}.`);
  });
});

newsletterForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const email = emailInput.value.trim();

  if (!email || !emailInput.validity.valid) {
    emailInput.setAttribute("aria-invalid", "true");
    emailError.textContent = "Enter a valid email address to join the insider list.";
    announce("Email address needs attention.");
    emailInput.focus();
    return;
  }

  emailInput.removeAttribute("aria-invalid");
  emailError.textContent = "";
  newsletterForm.reset();
  announce(`Thanks. ${email} has been added to the insider list.`);
});
