  overflow: hidden;
  height: 100%;
  border-radius: var(--radius-md);
}

.product-art {
  min-height: 16rem;
  border-bottom: 1px solid var(--color-border);
}

.product-art-coat {
  background:
    radial-gradient(circle at 50% 20%, #ffd58a 0 8%, transparent 9%),
    linear-gradient(120deg, transparent 35%, #32415d 36% 64%, transparent 65%),
    linear-gradient(145deg, #121827, #26180f);
}

.product-art-lamp {
  background:
    radial-gradient(ellipse at 50% 32%, #ffd58a 0 17%, #7e5429 18% 31%, transparent 32%),
    linear-gradient(90deg, transparent 49%, #f7f0e7 50% 51%, transparent 52%),
    linear-gradient(145deg, #161d2b, #21150e);
}

.product-art-bag {
  background:
    radial-gradient(ellipse at 50% 37%, transparent 0 17%, #ffd58a 18% 21%, transparent 22%),
    linear-gradient(180deg, transparent 28%, #433a34 29% 70%, transparent 71%),
    linear-gradient(145deg, #121827, #2d2018);
}

.product-card-body,
.deal-card,
.editorial-card {
  padding: 1.25rem;
}

.product-card-body p {
  color: var(--color-muted-text);
}

.product-purchase,
.deal-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 1.25rem;
}

.price,
.deal-price {
  color: var(--color-text);
  font-size: 1.35rem;
  font-weight: 900;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 1rem;
}

.deal-card {
  display: flex;
  min-height: 20rem;
  flex-direction: column;
  justify-content: space-between;
  border-radius: var(--radius-md);
}

.deal-card-featured {
  background:
    linear-gradient(135deg, #3a2515, transparent),
    var(--color-surface-strong);
}

.deal-card p {
  color: var(--color-muted-text);
}

.deal-was {
  color: var(--color-muted-text);
  text-decoration: line-through;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 1rem;
}

.editorial-card {
  display: grid;
  grid-template-columns: 9rem 1fr;
  gap: 1rem;
  align-items: center;
  border-radius: var(--radius-md);
}

.editorial-card-large {
  grid-row: span 2;
  grid-template-columns: 1fr;
  align-items: stretch;
}

.editorial-image {
  min-height: 9rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
}

.editorial-card-large .editorial-image {
  min-height: 21rem;
}

.editorial-image-one {
  background:
    linear-gradient(115deg, transparent 28%, #ffd58a 29% 33%, transparent 34%),
    linear-gradient(135deg, #151b28, #4a2a17);
}

.editorial-image-two {
  background:
    radial-gradient(circle at 45% 38%, #ffd58a 0 18%, transparent 19%),
    linear-gradient(135deg, #171d2b, #342014);
}

.editorial-image-three {
  background:
    linear-gradient(90deg, transparent 20%, #6a4a2b 21% 42%, transparent 43%),
    linear-gradient(135deg, #10141f, #2c3445);
}

.newsletter {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  margin-top: clamp(4rem, 8vw, 7rem);
  border-radius: var(--radius-lg);
  padding: clamp(1.35rem, 4vw, 2.3rem);
}

.newsletter p {
  color: var(--color-muted-text);
}

.newsletter-form label {
  display: block;
  margin-bottom: 0.45rem;
  font-weight: 900;
}

.newsletter-controls {
  display: flex;
  gap: 0.65rem;
}

input {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  background: #090c12;
  color: var(--color-text);
  padding: 0.8rem 1rem;
}

input::placeholder {
  color: #948c85;
}

input[aria-invalid="true"] {
  border-color: var(--color-danger);
}

.form-error {
  min-height: 1.5rem;
  margin: 0.5rem 0 0;
  color: var(--color-danger);
  font-weight: 700;
}

.cart-summary {
  margin-top: 1rem;
  border-radius: var(--radius-md);
  padding: 1.25rem;
}

.cart-summary p {
  margin-bottom: 0;
  color: var(--color-muted-text);
}

.status-region {
  position: fixed;
  right: 1rem;
  bottom: 1rem;
  max-width: min(24rem, calc(100vw - 2rem));
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: #0c1018;
  color: var(--color-success);
  padding: 0.8rem 1rem;
  box-shadow: var(--shadow-elevated);
}

.status-region:empty {
  display: none;
}

.site-footer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  border-top: 1px solid var(--color-border);
  padding-block: 2.5rem;
}

.site-footer p {
  max-width: 32rem;
  margin: 1rem 0 0;
  color: var(--color-muted-text);
}

.site-footer ul {
  display: flex;
  flex-wrap: wrap;
  justify-content: end;
  gap: 1rem;
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }

  .button,
  a,
  .product-card,
  .deal-card,
  .editorial-card {
    transition:
      transform 180ms ease,
      border-color 180ms ease,
      color 180ms ease,
      background-color 180ms ease;
  }

  .product-card:hover,
  .deal-card:hover,
  .editorial-card:hover {
    transform: translateY(-4px);
  }
}

@media (max-width: 880px) {
  .header-inner {
    grid-template-columns: auto auto auto;
  }

  .nav-toggle {
    display: inline-flex;
    min-height: 44px;
    align-items: center;
    justify-content: center;
    gap: 0.55rem;
    border: 1px solid var(--color-border);
    border-radius: 999px;
    background: var(--color-surface);
    color: var(--color-text);
    padding: 0.58rem 0.8rem;
    cursor: pointer;
  }

  .nav-toggle span:first-child {
    width: 1rem;
    height: 0.75rem;
    border-block: 2px solid currentColor;
  }

  .primary-nav {
    position: absolute;
    top: 100%;
    right: var(--space-page);
    left: var(--space-page);
    display: none;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    background: var(--color-surface);
    padding: 1rem;
    box-shadow: var(--shadow-elevated);
  }

  .primary-nav.is-open {
    display: block;
  }

  .primary-nav ul {
    flex-direction: column;
    align-items: stretch;
  }

  .primary-nav a {
    display: block;
    padding: 0.75rem;
  }

  .hero,
  .product-grid,
  .deals-grid,
  .editorial-grid,
  .newsletter,
  .site-footer {
    grid-template-columns: 1fr;
  }

  .hero {
    min-height: auto;
  }

  .section-heading,
  .product-purchase,
  .deal-footer,
  .newsletter-controls {
    align-items: stretch;
    flex-direction: column;
  }

  .button,
  .text-link {
    width: fit-content;
  }

  .newsletter-controls .button,
  .product-purchase .button,
  .deal-footer .button {
    width: 100%;
  }

  .site-footer ul {
    justify-content: start;
  }
}

@media (max-width: 560px) {
  .header-inner,
  .site-footer,
  main {
    width: min(100% - 2rem, 1180px);
  }

  .brand span:last-child,
  .cart-link span:first-child,
  .nav-toggle-label {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
  }

  .hero-copy {
    padding: 1.4rem;
  }

  .hero-stat-grid,
  .editorial-card {
    grid-template-columns: 1fr;
  }

  .editorial-image,
  .editorial-card-large .editorial-image {
    min-height: 12rem;
  }
}

@media (forced-colors: active) {
  .brand-mark,
  .button,
  .cart-count,
  .product-art,
  .editorial-image,
  .hero-panel::before,
  input {
    border: 2px solid ButtonBorder;
  }

  .hero-copy,
  .hero-panel,
  .product-card,
  .deal-card,
  .editorial-card,
  .newsletter,
  .cart-summary,
  .status-region,
  .primary-nav {
    border: 2px solid CanvasText;
    box-shadow: none;
  }
}
