         max-width: min(24rem, calc(100vw - 2rem));
         border: 1px solid var(--color-border);
         border-radius: var(--radius-sm);
         background: #0c1018;
         color: var(--color-success);
         padding: 0.8rem 1rem;
         box-shadow: var(--shadow-elevated);
       }

       .status-region:empty {
         display: none;
       }

       .site-footer {
         display: grid;
         grid-template-columns: 1fr auto;
         gap: 2rem;
         border-top: 1px solid var(--color-border);
         padding-block: 2.5rem;
       }

       .site-footer p {
         max-width: 32rem;
         margin: 1rem 0 0;
         color: var(--color-muted-text);
       }

       .site-footer ul {
         display: flex;
         flex-wrap: wrap;
         justify-content: end;
         gap: 1rem;
       }

       @media (prefers-reduced-motion: no-preference) {
         html {
           scroll-behavior: smooth;
         }

         .button,
         a,
         .product-card,
         .deal-card,
         .editorial-card {
           transition:
             transform 180ms ease,
             border-color 180ms ease,
             color 180ms ease,
             background-color 180ms ease;
         }

         .product-card:hover,
         .deal-card:hover,
         .editorial-card:hover {
           transform: translateY(-4px);
         }
       }

       @media (max-width: 880px) {
         .header-inner {
           grid-template-columns: auto auto auto;
         }

         .nav-toggle {
           display: inline-flex;
           min-height: 44px;
           align-items: center;
           justify-content: center;
           gap: 0.55rem;
           border: 1px solid var(--color-border);
           border-radius: 999px;
           background: var(--color-surface);
           color: var(--color-text);
           padding: 0.58rem 0.8rem;
           cursor: pointer;
         }

         .nav-toggle span:first-child {
           width: 1rem;
           height: 0.75rem;
           border-block: 2px solid currentColor;
         }

         .primary-nav {
           position: absolute;
           top: 100%;
           right: var(--space-page);
           left: var(--space-page);
           display: none;
           border: 1px solid var(--color-border);
           border-radius: var(--radius-md);
           background: var(--color-surface);
           padding: 1rem;
           box-shadow: var(--shadow-elevated);
         }

         .primary-nav.is-open {
           display: block;
         }

         .primary-nav ul {
           flex-direction: column;
           align-items: stretch;
         }

         .primary-nav a {
           display: block;
           padding: 0.75rem;
         }

         .hero,
         .product-grid,
         .deals-grid,
         .editorial-grid,
         .newsletter,
         .site-footer {
           grid-template-columns: 1fr;
         }

         .hero {
           min-height: auto;
         }

         .section-heading,
         .product-purchase,
         .deal-footer,
         .newsletter-controls {
           align-items: stretch;
           flex-direction: column;
         }

         .button,
         .text-link {
           width: fit-content;
         }

         .newsletter-controls .button,
         .product-purchase .button,
         .deal-footer .button {
           width: 100%;
         }

         .site-footer ul {
           justify-content: start;
         }
       }

       @media (max-width: 560px) {
         .header-inner,
         .site-footer,
         main {
           width: min(100% - 2rem, 1180px);
         }

         .brand span:last-child,
         .cart-link span:first-child,
         .nav-toggle-label {
           clip: rect(0 0 0 0);
           clip-path: inset(50%);
           height: 1px;
           overflow: hidden;
           position: absolute;
           white-space: nowrap;
           width: 1px;
         }

         .hero-copy {
           padding: 1.4rem;
         }

         .hero-stat-grid,
         .editorial-card {
           grid-template-columns: 1fr;
         }

         .editorial-image,
         .editorial-card-large .editorial-image {
           min-height: 12rem;
         }
       }

       @media (forced-colors: active) {
         .brand-mark,
         .button,
         .cart-count,
         .product-art,
         .editorial-image,
         .hero-panel::before,
         input {
           border: 2px solid ButtonBorder;
         }

         .hero-copy,
         .hero-panel,
         .product-card,
         .deal-card,
         .editorial-card,
         .newsletter,
         .cart-summary,
         .status-region,
         .primary-nav {
           border: 2px solid CanvasText;
           box-shadow: none;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <header class="site-header">
       <div class="header-inner">
         <a class="brand" href="/">
           <span class="brand-mark" aria-hidden="true">N9</span>
           <span>North &amp; Ninth</span>
         </a>

         <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="primary-navigation">
           <span aria-hidden="true"></span>
           <span class="nav-toggle-label">Menu</span>
