             <li><a href="#editorial">Stories</a></li>
             <li><a href="#newsletter">Insider list</a></li>
           </ul>
         </nav>

         <a class="cart-link" href="#cart-summary" aria-label="Bag, shopping bag with 0 items">
           <span>Bag</span>
