               <h3><a href="/editorial/three-ways-to-style-technical-tailoring">Three ways to style technical tailoring</a></h3>
               <p>Our buyers break down texture, proportion, and utility details for transitional weather.</p>
             </div>
           </article>
           <article class="editorial-card">
             <div class="editorial-image editorial-image-two" aria-hidden="true"></div>
             <div>
               <p class="product-meta">Home notes</p>
               <h3><a href="/editorial/lighting-a-darker-room">Lighting a darker room without losing atmosphere</a></h3>
             </div>
           </article>
           <article class="editorial-card">
             <div class="editorial-image editorial-image-three" aria-hidden="true"></div>
             <div>
               <p class="product-meta">Interview</p>
               <h3><a href="/editorial/makers-series-sable-studio">Makers Series: Sable Studio on considered accessories</a></h3>
             </div>
           </article>
         </div>
       </section>

       <section class="newsletter" id="newsletter" aria-labelledby="newsletter-heading">
         <div>
           <p class="eyebrow">Insider list</p>
           <h2 id="newsletter-heading">Get early access to drops and private deals.</h2>
           <p id="newsletter-help">
             Fields marked with <span aria-hidden="true">*</span> are required. No spam. Just launch notes,
             editorial picks, and member-only credits.
           </p>
         </div>
         <form class="newsletter-form" novalidate>
           <label for="email">Email address <span aria-hidden="true">*</span></label>
           <div class="newsletter-controls">
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               placeholder="you@example.com"
               aria-describedby="newsletter-help email-error"
               required
             >
             <button type="submit" class="button button-primary">Join list</button>
           </div>
           <p class="form-error" id="email-error"></p>
         </form>
       </section>

       <section class="cart-summary" id="cart-summary" aria-labelledby="cart-summary-heading">
         <h2 id="cart-summary-heading">Shopping bag summary</h2>
         <p><span class="cart-count-text">0 items</span> added during this visit.</p>
       </section>

       <div class="status-region" role="status" aria-live="polite" aria-atomic="true"></div>
     </main>

     <footer class="site-footer">
       <div>
         <a class="brand footer-brand" href="/">
           <span class="brand-mark" aria-hidden="true">N9</span>
           <span>North &amp; Ninth</span>
         </a>
         <p>Retail objects, apparel, and ideas selected for modern city living.</p>
       </div>
       <nav aria-label="Footer">
         <ul>
           <li><a href="/about">About</a></li>
           <li><a href="/shipping">Shipping</a></li>
           <li><a href="/returns">Returns</a></li>
           <li><a href="/contact">Contact</a></li>
         </ul>
       </nav>
     </footer>

     <script>
       const navToggle = document.querySelector(".nav-toggle");
       const primaryNav = document.querySelector("#primary-navigation");
       const cartLink = document.querySelector(".cart-link");
       const cartCount = document.querySelector(".cart-count");
       const cartCountText = document.querySelector(".cart-count-text");
       const statusRegion = document.querySelector(".status-region");
       const addToCartButtons = document.querySelectorAll(".add-to-cart");
       const newsletterForm = document.querySelector(".newsletter-form");
       const emailInput = document.querySelector("#email");
       const emailError = document.querySelector("#email-error");

       let bagCount = 0;
       let statusTimer;

       function announce(message) {
         window.clearTimeout(statusTimer);
         statusRegion.textContent = message;
         statusTimer = window.setTimeout(() => {
           statusRegion.textContent = "";
         }, 4500);
       }

       function setNavOpen(isOpen) {
         navToggle.setAttribute("aria-expanded", String(isOpen));
         primaryNav.classList.toggle("is-open", isOpen);
         document.body.classList.toggle("nav-open", isOpen);
       }

       navToggle.addEventListener("click", () => {
         const isOpen = navToggle.getAttribute("aria-expanded") === "true";
         setNavOpen(!isOpen);
       });

       primaryNav.addEventListener("click", (event) => {
         if (event.target.closest("a")) {
           setNavOpen(false);
         }
       });

       document.addEventListener("keydown", (event) => {
         if (event.key === "Escape" && navToggle.getAttribute("aria-expanded") === "true") {
           setNavOpen(false);
           navToggle.focus();
         }
       });

       addToCartButtons.forEach((button) => {
         const productName = button.dataset.product;
         button.setAttribute("aria-label", `${button.textContent.trim()}: ${productName}`);

         button.addEventListener("click", () => {
           bagCount += 1;
           cartCount.textContent = String(bagCount);
           cartCountText.textContent = `${bagCount} ${bagCount === 1 ? "item" : "items"}`;
           cartLink.setAttribute(
             "aria-label",
             `Bag, shopping bag with ${bagCount} ${bagCount === 1 ? "item" : "items"}`
           );
           announce(`${productName} added to bag. Bag now has ${bagCount} ${bagCount === 1 ? "item" : "items"}.`);
         });
       });

       newsletterForm.addEventListener("submit", (event) => {
         event.preventDefault();
         const email = emailInput.value.trim();

         if (!email || !emailInput.validity.valid) {
           emailInput.setAttribute("aria-invalid", "true");
           emailError.textContent = "Error: Enter a valid email address to join the insider list.";
           announce("Email address needs attention.");
           emailInput.focus();
           return;
         }

         emailInput.removeAttribute("aria-invalid");
         emailError.textContent = "";
         newsletterForm.reset();
         announce(`Thanks. ${email} has been added to the insider list.`);
       });
     </script>
   </body>
 </html>

')
